 var frame=BitmapDecoder.Create(new Uri(source),BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.OnLoad).Frames[0];var wic=new ColorConvertedBitmap(new FormatConvertedBitmap(frame,PixelFormats.Bgra32,null,0),new ColorContext(new Uri(Path.Combine(output,"DisplayP3.icc"))),new ColorContext(new Uri(Path.Combine(output,"sRGB.icc"))),PixelFormats.Bgra32);var wicCodes=new byte[36];wic.CopyPixels(wicCodes,36,0);var differences=Enumerable.Range(0,27).Select(i=>Math.Abs(wicCodes[i/3*4+2-i%3]/255d-Math.Clamp(expected[i],0,1))*255).ToArray();File.WriteAllText(Path.Combine(output,"WIC_REFERENCE_DIAGNOSTIC.json"),JsonSerializer.Serialize(new{expected,wicCodes,differences}));var inGamutDifferences=Enumerable.Range(0,9).Where(p=>expected.Skip(p*3).Take(3).All(v=>v>=0&&v<=1)).SelectMany(p=>differences.Skip(p*3).Take(3)).ToArray();Assert.IsTrue(inGamutDifferences.Max()<3,"Windows WIC 8bit reference, in-gamut only; out-of-gamut clipping behavior recorded separately, not hidden");
