 using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs(output));await vm.LoadTargetAsync(source);Assert.IsTrue(vm.ActiveTarget is not null||vm.FailedTarget is not null,"explicit managed import can recover legacy WIC unsupported preview");vm.ManagedOutputSpace="DisplayP3";await vm.CreateManagedColorVariantAsync();Assert.IsNotNull(vm.ActiveTarget,"created color variant: "+vm.StatusText);Assert.IsNotNull(vm.ActiveTarget.RawDefinition,"created color definition: "+vm.StatusText);Assert.IsNotNull(vm.ActiveTarget.RawDefinition.ColorState,vm.StatusText);Assert.AreEqual("Embedded",vm.ActiveTarget.RawDefinition.ColorState.InputPolicy);vm.Editor.SetToolParameter(ColorStudioToolCatalog.GetParameters(ColorStudioNodeType.BasicTone).Single(x=>x.Key=="exposure"),-.3);await vm.RawLocalPreviewWork;var project=Path.Combine(output,"color-"+Guid.NewGuid().ToString("N")+".ptstudio.json");await vm.SaveSessionAsync(project);var frozen=JsonSerializer.Serialize(vm.ActiveTarget.RawDefinition);vm.SetManualMonitorProfile(Path.Combine(output,"DisplayP3.icc"));vm.ExplicitSdrDisplayColor=false;await vm.SaveSessionAsync(project);using var reopened=new ReferenceColorWorkspaceViewModel(new Dialogs(output));await reopened.LoadSessionAsync(project);Assert.IsNotNull(reopened.ActiveTarget,"reopen color: "+reopened.StatusText);Assert.AreEqual(frozen,JsonSerializer.Serialize(reopened.ActiveTarget!.RawDefinition));Assert.AreEqual(p3.Sha256,reopened.ManualMonitorProfile!.Sha256);reopened.QuickExportFormat=StudioExportFormat.Tiff;reopened.ActiveTarget.IsSelected=true;await reopened.ExportSelectedCommand.ExecuteAsync(null);Assert.AreEqual(ReferenceExportStatus.Succeeded,reopened.ActiveTarget.ExportStatus,reopened.ActiveTarget.Error);Assert.AreEqual(p3.Sha256,DocumentColorWorkflowV1.InspectInput(reopened.ActiveTarget.OutputPath!,cms).Profile.Sha256);Assert.AreEqual(p3.Sha256,reopened.ActiveTarget.RawDefinition!.ColorState!.Output.Sha256);reopened.ManagedOutputSpace="AdobeRGB";reopened.SetManagedOutputProfile();Assert.AreEqual(adobe.Sha256,reopened.ActiveTarget.RawDefinition.ColorState.Output.Sha256);await reopened.PhotoGradeUndoCommand.ExecuteAsync(null);Assert.AreEqual(p3.Sha256,reopened.ActiveTarget.RawDefinition.ColorState.Output.Sha256);
 File.WriteAllText(Path.Combine(output,"CMS_CLOSURE.json"),JsonSerializer.Serialize(new{source=source,inputProfile=p3.Sha256,working=srgb.Sha256,outputs,wicReferenceMax8=differences.Max(),wicReferenceMean8=differences.Average(),wicInGamutMax8=inGamutDifferences.Max(),wicOutOfGamutEquivalence=false,engine=LcmsRgbEngine.Version,librarySha=LcmsRgbEngine.ExpectedSha,CalibrationEligible=false,scope="Actual LCMS float + WIC independent profile conversion + TIFF16/PNG16 ICC readback; no physical monitor or camera calibration"},new JsonSerializerOptions{WriteIndented=true}));
