 [TestMethod]public void ProfileContentIdentityAssignConvertAndCorruptionPolicies(){using var cms=new LcmsRgbEngine();var p=cms.StandardProfile("DisplayP3");var s=cms.StandardProfile("sRGB");Assert.AreEqual(s.Sha256,cms.StandardProfile("sRGB").Sha256);using var transform=cms.CreateTransform(p,s);var input=new float[]{.7f,.2f,.1f};var converted=transform.Convert(input);Assert.IsFalse(input.SequenceEqual(converted),"conversion changes codes, assignment alone does not");var corrupt=p.Bytes();corrupt[36]=0;Assert.ThrowsExactly<InvalidDataException>(()=>RgbIccIdentityV1.FromBytes(corrupt,"same name"));Assert.ThrowsExactly<InvalidDataException>(()=>(p with{Sha256=s.Sha256}).Bytes());var legacy=new ProfessionalRawDefinition();Assert.IsFalse(JsonSerializer.Serialize(legacy).Contains("ColorState"));Assert.ThrowsExactly<NotSupportedException>(()=>(legacy with{ColorState=new(s,s,p)}).Validate());}
 [TestMethod]public Task ExplicitMonitorTransformChangesOnlyPresentationAndNeverExportRecipe()=>RunSta(async()=>{
 EnsureTestApplication();using var cms=new LcmsRgbEngine();var p3=cms.StandardProfile("DisplayP3");var bytes=Enumerable.Range(0,32*16*3).Select(i=>(byte)(20+i%210)).ToArray();var bitmap=BitmapSource.Create(32,16,96,96,PixelFormats.Rgb24,null,bytes,96);bitmap.Freeze();var viewport=new RAWSelectionAssistant.Views.ColorStudioImageViewport{Matched=bitmap,Original=bitmap,Mode="仿色",ManualDisplayProfile=p3,DisplayColorEnabled=true};await viewport.DisplayColorWork;var display=viewport.PresentedDisplayPixels(bitmap);Assert.AreNotSame(bitmap,display);Assert.AreSame(bitmap,viewport.Matched);var expected=MonitorRgbDisplayV1.Convert(bitmap,p3);CollectionAssert.AreEqual(Pixels(expected),Pixels(display));var legacy=new RAWSelectionAssistant.Views.ColorStudioImageViewport{Matched=bitmap,Mode="仿色"};Assert.AreSame(bitmap,legacy.PresentedDisplayPixels(bitmap));viewport.ManualDisplayProfile=cms.StandardProfile("AdobeRGB");await viewport.DisplayColorWork;CollectionAssert.AreEqual(Pixels(MonitorRgbDisplayV1.Convert(bitmap,viewport.ManualDisplayProfile)),Pixels(viewport.PresentedDisplayPixels(bitmap)));var missing=MonitorRgbDisplayV1.Resolve(new("test","NoAssociation",null,null,0),null);Assert.IsNull(missing.Profile);StringAssert.Contains(missing.State,"FallbackSrgb");
 // WPF offscreen of untagged CPU output proves only app composition, not physical monitor/ACM behavior.
 viewport.Measure(new System.Windows.Size(320,160));viewport.Arrange(new System.Windows.Rect(0,0,320,160));var rendered=new RenderTargetBitmap(320,160,96,96,PixelFormats.Pbgra32);rendered.Render(viewport);Assert.AreSame(bitmap,viewport.Matched);var dir=Environment.GetEnvironmentVariable("KITAO_HOME_CMS");if(dir is not null)File.WriteAllText(Path.Combine(dir,"DISPLAY_PATH.json"),JsonSerializer.Serialize(new{manualExact=true,originalBitmapUnmodified=true,profileSwitchUpdated=true,defaultDisabled=true,wpfUntaggedComposition=true,physicalMonitorAndAcm="NOT_VERIFIED",gpuLutUsed=false}));viewport.RaiseEvent(new System.Windows.RoutedEventArgs(System.Windows.FrameworkElement.UnloadedEvent));
 });
 [TestMethod]public Task NewBlendModePreviewMaskSaveReopenLosslessOutputAgrees()=>RunSta(async()=>{EnsureTestApplication();var root=Path.Combine(Path.GetTempPath(),"home-blend-output-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{var file=Path.Combine(root,"source.png");StudioQuickExport.Encode(BitmapSource.Create(60,40,96,96,PixelFormats.Rgb24,null,Enumerable.Range(0,7200).Select(x=>(byte)(x%230)).ToArray(),180),file,file,StudioExportFormat.Png);using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs(root));await vm.LoadTargetAsync(file);vm.Editor.SetToolParameter(ColorStudioToolCatalog.GetParameters(ColorStudioNodeType.BasicTone).Single(x=>x.Key=="exposure"),.4);vm.Editor.SelectedLayerBlend=StudioLayerBlend.Darken;vm.Editor.SelectedLayerOpacity=.7;vm.Editor.AddMaskStroke(new([new(.25,.5)],.2,.5,.8,1));await vm.Editor.ApplyCommand.ExecuteAsync(null);await vm.LayerThumbnailWork;Assert.AreEqual(2,vm.Editor.SelectedAdjustmentNode!.CompositeVersion);vm.Editor.SelectedLayerBlend=StudioLayerBlend.Overlay;Assert.AreEqual(StudioLayerBlend.Overlay,vm.Editor.SelectedLayerBlend);await vm.Editor.ApplyCommand.ExecuteAsync(null);var before=Pixels(vm.Editor.MatchedImage!);var project=Path.Combine(root,"blend.ptstudio.json");await vm.SaveSessionAsync(project);using var reopened=new ReferenceColorWorkspaceViewModel(new Dialogs(root));await reopened.LoadSessionAsync(project);await reopened.Editor.ApplyCommand.ExecuteAsync(null);CollectionAssert.AreEqual(before,Pixels(reopened.Editor.MatchedImage!));reopened.ActiveTarget!.IsSelected=true;await reopened.ExportSelectedCommand.ExecuteAsync(null);Assert.AreEqual(ReferenceExportStatus.Succeeded,reopened.ActiveTarget.ExportStatus,reopened.ActiveTarget.Error);CollectionAssert.AreEqual(before,Pixels(StudioQuickExport.Load(reopened.ActiveTarget.OutputPath!)));}finally{Directory.Delete(root,true);}});
 [TestMethod]public Task IndependentReferenceSamplesAndActualCameraDerivativeCmsClosure()=>RunSta(async()=>{
 EnsureTestApplication();var dir=Environment.GetEnvironmentVariable("KITAO_HOME_CMS");if(dir is null){Assert.Inconclusive("Explicit CMS reference output");return;}Directory.CreateDirectory(dir);using var cms=new LcmsRgbEngine();var spaces=new[]{"sRGB","DisplayP3","AdobeRGB","ProPhotoRGB"};var input=Enumerable.Range(0,256).SelectMany(i=>new float[]{i/255f,(255-i)/255f,(i%53)/52f}).Concat(new float[]{.0001f,.0001f,.0001f,.55f,.32f,.23f,1.1f,-.02f,.6f}).ToArray();var rows=new List<object>();foreach(var from in spaces)foreach(var to in spaces){var a=cms.StandardProfile(from);var b=cms.StandardProfile(to);using var t=cms.CreateTransform(a,b);var values=t.Convert(input);rows.Add(new{from,to,input,output=values});WriteProfile(Path.Combine(dir,from+".icc"),a.Bytes());}File.WriteAllText(Path.Combine(dir,"LCMS_FLOAT_REFERENCE_INPUT.json"),JsonSerializer.Serialize(rows));
 // Existing explicitly authorized Canon derivative through real LibRaw -> sRGB TIFF16, then new ICC import/edit/export.
 var source=Environment.GetEnvironmentVariable("KITAO_AUTHORIZED_CANON_CR3")??"N:/pixart/RAW/Real/canon/TNAN8886.CR3";Assert.AreEqual("B7D358517DB0CD5B5C54215AA089A5A30C79234AEF50E9381931128493E33401",Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(source))));var decoder=new ProfessionalRawDecoder();var definition=new ProfessionalRawDefinition();var master=await decoder.DecodeAsync(source,definition);using var owned=master.Image;using var preview=ProfessionalRawPipeline.RenderPreview(master,definition,512);var tagged=Path.Combine(dir,"canon-authorized-srgb.tif");if(File.Exists(tagged))File.Delete(tagged);await AtomicTiffWriter.WriteRgb48Async(tagged,preview,new(IccProfile:StudioQuickExport.SrgbProfileBytes()));var inputProfile=DocumentColorWorkflowV1.InspectInput(tagged,cms).Profile;var managed=InstantFilmJpegInput.Definition with{RenderedInputVersion=2,ColorState=new(inputProfile,cms.StandardProfile("sRGB"),cms.StandardProfile("DisplayP3"))};var photo=await DocumentColorWorkflowV1.ReadAsync(tagged,managed,CancellationToken.None);using var image=photo.Image;var output=Path.Combine(dir,"canon-derived-p3.tif");if(File.Exists(output))File.Delete(output);var check=await DocumentColorWorkflowV1.WriteAsync(photo,managed,output,StudioExportFormat.Tiff,CancellationToken.None);Assert.AreEqual(0,check.MaximumError);File.WriteAllText(Path.Combine(dir,"REAL_DERIVATIVE_CMS.json"),JsonSerializer.Serialize(new{sourceHash=master.Contract.SourceSha256,derivativeNotSensorRaw=true,preview.Width,preview.Height,check.MaximumError,inputProfile=inputProfile.Sha256,outputProfile=managed.ColorState.Output.Sha256,CalibrationEligible=false}));
 });
 [TestMethod]public Task ExplicitMissingProfileAlphaPolicyAndMonitorExportSeparationAreTraced()=>RunSta(async()=>{EnsureTestApplication();var root=Path.Combine(Path.GetTempPath(),"cms-policy-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{using var cms=new LcmsRgbEngine();var file=Path.Combine(root,"untagged.png");var a=new byte[]{20,40,80,128,80,40,20,0};var rgba=BitmapSource.Create(2,1,96,96,PixelFormats.Bgra32,null,a,8);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(rgba));using(var stream=File.Create(file))png.Save(stream);var inspect=DocumentColorWorkflowV1.InspectInput(file,cms);Assert.AreEqual("UntaggedExplicitSrgb",inspect.Policy);var definition=InstantFilmJpegInput.Definition with{RenderedInputVersion=2,ColorState=new(inspect.Profile,cms.StandardProfile("sRGB"),cms.StandardProfile("AdobeRGB"),inspect.Policy)};var master=await DocumentColorWorkflowV1.ReadAsync(file,definition,CancellationToken.None);using var pixels=master.Image;Assert.AreEqual(1,master.Image.Rgb32.Span[3],1e-5,"V1 transparent input flatten white policy is explicit, no fake alpha preservation");var one=Path.Combine(root,"before.tif");var two=Path.Combine(root,"after.tif");await DocumentColorWorkflowV1.WriteAsync(master,definition,one,StudioExportFormat.Tiff,CancellationToken.None);var frozen=JsonSerializer.Serialize(definition);using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs(root));vm.SetManualMonitorProfile(null);vm.ExplicitSdrDisplayColor=true;await DocumentColorWorkflowV1.WriteAsync(master,definition,two,StudioExportFormat.Tiff,CancellationToken.None);Assert.AreEqual(frozen,JsonSerializer.Serialize(definition));using var s1=File.OpenRead(one);using var s2=File.OpenRead(two);var t1=TiffStreamValidator.Validate(s1);var t2=TiffStreamValidator.Validate(s2);Assert.AreEqual(t1.PixelSha256,t2.PixelSha256);CollectionAssert.AreEqual(t1.IccProfile,t2.IccProfile);}finally{Directory.Delete(root,true);}});
 [TestMethod]public Task JpegIccActualCodesProfileAndMonitorAssociationEvidence()=>RunSta(async()=>{EnsureTestApplication();var dir=Environment.GetEnvironmentVariable("KITAO_HOME_CMS")??Path.Combine(Path.GetTempPath(),"cms-jpeg-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);using var cms=new LcmsRgbEngine();var srgb=cms.StandardProfile("sRGB");var p3=cms.StandardProfile("DisplayP3");var data=new float[128*32*3];for(int y=0;y<32;y++)for(int x=0;x<128;x++){int i=(y*128+x)*3;data[i]=.1f+.7f*x/127;data[i+1]=.1f+.5f*y/31;data[i+2]=.3f;}using var image=new HighBitDepthImageBuffer(128,32,data,"16","sRGB");var d=InstantFilmJpegInput.Definition with{RenderedInputVersion=2,ColorState=new(srgb,srgb,p3)};var master=new ProfessionalRawMaster(image,new("TestRgb","Rendered","RGB",new string('a',64),d.DecodeKey,[],[],[],65535,OutputSpace:"sRGB",WhiteBalanceApplied:false,CameraMatrixApplied:false,Gamma:"sRGB"));var file=Path.Combine(dir,"smooth-p3.jpg");if(File.Exists(file))File.Delete(file);await DocumentColorWorkflowV1.WriteAsync(master,d,file,StudioExportFormat.Jpeg,CancellationToken.None);var check=DocumentColorWorkflowV1.Inspect(file,master,d,StudioExportFormat.Jpeg);Assert.IsTrue(check.MeanAbsoluteError<=5);using var topology=new WindowsDisplayTopologyService(false);var observations=topology.GetDisplays().Select(x=>WindowsMonitorProfileProbe.ObserveDevice(x.DeviceName)).ToArray();File.WriteAllText(Path.Combine(dir,"JPEG_AND_MONITOR_OBSERVATIONS.json"),JsonSerializer.Serialize(new{check,observations,physicalScreenAccuracy=false,actualWindowMovementTest="NOT_RUN",systemAcmHdr="UNVERIFIED_EXPLICIT_PATH_DEFAULT_OFF"},new JsonSerializerOptions{WriteIndented=true}));});
 [TestMethod]public void CmsEngineRetiresOnlyAfterInFlightTransformLease(){var cms=new LcmsRgbEngine();var s=cms.StandardProfile("sRGB");var p=cms.StandardProfile("DisplayP3");using var transform=cms.CreateTransform(s,p);cms.Dispose();Assert.ThrowsExactly<ObjectDisposedException>(()=>cms.CreateTransform(s,p));var values=transform.Convert(new float[]{.2f,.3f,.4f});Assert.IsTrue(values.All(float.IsFinite));}
 [TestMethod]public Task ColorStateAndProfilesRoundtripWithoutMigratingLegacyOrChangingAssignedCodes()=>RunSta(async()=>{EnsureTestApplication();var root=Path.Combine(Path.GetTempPath(),"cms-assign-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{using var cms=new LcmsRgbEngine();var s=cms.StandardProfile("sRGB");var p=cms.StandardProfile("DisplayP3");var file=Path.Combine(root,"tagged.tif");using var pixels=new HighBitDepthImageBuffer(16,8,Enumerable.Repeat(.3f,16*8*3).ToArray(),"16","sRGB");await AtomicTiffWriter.WriteRgb48Async(file,pixels,new(IccProfile:p.Bytes()));var original=File.ReadAllBytes(file);using var vm=new ReferenceColorWorkspaceViewModel(new Dialogs(root));await vm.LoadTargetAsync(file);await vm.CreateManagedColorVariantAsync();Assert.IsNotNull(vm.ActiveTarget?.RawDefinition?.ColorState,vm.StatusText);var converted=vm.ActiveTarget.LinearRawMaster!.Image.Rgb32.ToArray();var oldId=vm.ActiveTarget.ActiveEditVersionId;vm.AssignedInputSpace="sRGB";await vm.CreateManagedColorVariantAsync(true);Assert.AreEqual("AssignExplicitProfile",vm.ActiveTarget.RawDefinition!.ColorState!.InputPolicy);Assert.AreEqual(s.Sha256,vm.ActiveTarget.RawDefinition.ColorState.Input.Sha256);Assert.AreNotEqual(oldId,vm.ActiveTarget.ActiveEditVersionId);CollectionAssert.AreEqual(original,File.ReadAllBytes(file));Assert.AreEqual(.3,vm.ActiveTarget.LinearRawMaster!.Image.Rgb32.Span[0],.0001);await vm.SwitchEditVersionAsync(oldId!.Value);CollectionAssert.AreEqual(converted,vm.ActiveTarget.LinearRawMaster!.Image.Rgb32.ToArray());var legacy=new ProfessionalRawDefinition();Assert.IsFalse(JsonSerializer.Serialize(legacy).Contains("ColorState"));}finally{Directory.Delete(root,true);}});
 static void WriteProfile(string file,byte[] bytes){if(File.Exists(file)){CollectionAssert.AreEqual(bytes,File.ReadAllBytes(file),"same content identity fixture, do not rewrite WIC-open profile");return;}File.WriteAllBytes(file,bytes);}
 static byte[] Pixels(BitmapSource bitmap){var converted=new FormatConvertedBitmap(bitmap,PixelFormats.Bgra32,null,0);var a=new byte[bitmap.PixelWidth*bitmap.PixelHeight*4];converted.CopyPixels(a,bitmap.PixelWidth*4,0);return a;}
